    void refreshRemoteQr(){if(remoteServer==null||remoteQr==null)return;if(remoteServer.pairingExpired())remoteServer.rotatePairing();String pin=remoteServer.pin(),payload=remoteAddress()+"#pair="+pin;remotePairCode.setText(tr("Pairing code")+"  "+pin);if(payload.equals(remoteQrPayload))return;try{com.google.zxing.common.BitMatrix bits=new com.google.zxing.qrcode.QRCodeWriter().encode(payload,com.google.zxing.BarcodeFormat.QR_CODE,384,384);Bitmap code=Bitmap.createBitmap(384,384,Bitmap.Config.ARGB_8888);int[] pixels=new int[384*384];for(int y=0;y<384;y++)for(int x=0;x<384;x++)pixels[y*384+x]=bits.get(x,y)?0xff111522:Color.WHITE;code.setPixels(pixels,0,384,0,0,384,384);remoteQr.setImageBitmap(code);remoteQr.setContentDescription(tr("Open the phone remote"));remoteQrPayload=payload;}catch(com.google.zxing.WriterException e){android.util.Log.w("MiTVRemote","QR code unavailable",e);}}
