    void showNotice(String message,long duration){if(root==null)return;if(hideNotice!=null)handler.removeCallbacks(hideNotice);if(homeNotice!=null)root.removeView(homeNotice);TextView notice=text(message,14,WHITE);notice.setMaxWidth(dp(540));notice.setSingleLine(true);notice.setEllipsize(android.text.TextUtils.TruncateAt.END);notice.setPadding(dp(18),dp(13),dp(18),dp(13));notice.setBackground(surface(0xee202737,18));notice.setElevation(dp(12));FrameLayout.LayoutParams p=new FrameLayout.LayoutParams(-2,dp(46),Gravity.TOP|Gravity.LEFT);p.leftMargin=dp(50);p.topMargin=dp(22);root.addView(notice,p);homeNotice=notice;notice.setAlpha(.9f);notice.setTranslationY(-dp(8));if(motionEnabled())notice.animate().alpha(1f).translationY(0).setDuration(180).setInterpolator(easeOut()).start();hideNotice=()->{if(homeNotice==notice){if(motionEnabled())notice.animate().alpha(0f).translationY(-dp(5)).setDuration(140).setInterpolator(easeOut()).withEndAction(()->root.removeView(notice)).start();else root.removeView(notice);homeNotice=null;}hideNotice=null;};handler.postDelayed(hideNotice,duration);}
    boolean isInside(View child,View ancestor){if(child==null||ancestor==null)return false;View current=child;while(current!=null){if(current==ancestor)return true;android.view.ViewParent parent=current.getParent();current=parent instanceof View?(View)parent:null;}return false;}
    void remoteCommand(String cmd){if(cmd.equals("home")){resetHome();return;}if(cmd.equals("volumeup")||cmd.equals("volumedown")){android.media.AudioManager am=(android.media.AudioManager)getSystemService(AUDIO_SERVICE);am.adjustStreamVolume(android.media.AudioManager.STREAM_MUSIC,cmd.equals("volumeup")?android.media.AudioManager.ADJUST_RAISE:android.media.AudioManager.ADJUST_LOWER,0);return;}if(nativeReceiver!=null){if(cmd.equals("playpause")){nativeReceiver.togglePlayPause();return;}if(cmd.equals("next")||cmd.equals("previous")){if(nativeReceiver.getDacpController()!=null){if(cmd.equals("next"))nativeReceiver.getDacpController().nextItem();else nativeReceiver.getDacpController().prevItem();}return;}}if(cmd.equals("back")){if(panel!=null&&panel.isShowing())closePanel();else if(audioPopup!=null&&audioPopup.isShowing())audioPopup.dismiss();else onBackPressed();return;}View current=audioPopup!=null&&audioPopup.isShowing()?audioPopup.getContentView().findFocus():panel!=null&&panel.isShowing()?panel.getCurrentFocus():getCurrentFocus();if(current==null)current=root;if(cmd.equals("ok")){if(current!=null)current.performClick();return;}int direction;switch(cmd){case "up":direction=View.FOCUS_UP;break;case "down":direction=View.FOCUS_DOWN;break;case "left":direction=View.FOCUS_LEFT;break;case "right":direction=View.FOCUS_RIGHT;break;default:return;}if(scroll.navigate(current,direction))return;View next=current==null?null:current.focusSearch(direction);if(next!=null)next.requestFocus();}
