    void capturePopupBackdrop(){
        if(root.getWidth()==0||root.getHeight()==0)return;int w=Math.max(1,root.getWidth()/8),h=Math.max(1,root.getHeight()/8);Bitmap fresh=Bitmap.createBitmap(w,h,Bitmap.Config.ARGB_8888);Canvas scene=new Canvas(fresh);scene.scale(w/(float)root.getWidth(),h/(float)root.getHeight());root.draw(scene);int[] data=new int[w*h];fresh.getPixels(data,0,w,0,0,w,h);
        for(int pass=0;pass<5;pass++){int[] next=new int[data.length];for(int y=0;y<h;y++)for(int x=0;x<w;x++){int r=0,g=0,b=0,n=0;for(int dy=-2;dy<=2;dy++)for(int dx=-2;dx<=2;dx++){int color=data[Math.max(0,Math.min(h-1,y+dy))*w+Math.max(0,Math.min(w-1,x+dx))];r+=Color.red(color);g+=Color.green(color);b+=Color.blue(color);n++;}next[y*w+x]=Color.rgb(r/n,g/n,b/n);}data=next;}
        fresh.setPixels(data,0,w,0,0,w,h);popupBackdrop=fresh;
    }
    final class FrostedDock extends Drawable {final View owner;final boolean popup,musicGlass;final Paint p=new Paint(3);final RectF rect=new RectF();final int[] position=new int[2],origin=new int[2];FrostedDock(View v){this(v,false);}FrostedDock(View v,boolean popup){this(v,popup,false);}FrostedDock(View v,boolean popup,boolean musicGlass){owner=v;this.popup=popup;this.musicGlass=musicGlass;}public void setAlpha(int a){}public void setColorFilter(ColorFilter f){}public int getOpacity(){return PixelFormat.TRANSLUCENT;}public void draw(Canvas c){rect.set(getBounds());p.setColor(Color.WHITE);p.setStyle(Paint.Style.FILL);if(popup&&popupBackdrop!=null){c.save();Path clip=new Path();clip.addRoundRect(rect,dp(22),dp(22),Path.Direction.CW);c.clipPath(clip);owner.getLocationOnScreen(position);root.getLocationOnScreen(origin);float x=position[0]-origin[0],y=position[1]-origin[1];c.drawBitmap(popupBackdrop,null,new RectF(-x,-y,root.getWidth()-x,root.getHeight()-y),p);c.restore();}p.setShader(new LinearGradient(0,rect.top,0,rect.bottom,musicGlass?new int[]{0xeb000000,0xe0000000}:popup?new int[]{0xb0353b4c,0xc01b2130}:new int[]{0x99444b64,0x99202739},null,Shader.TileMode.CLAMP));c.drawRoundRect(rect,dp(22),dp(22),p);p.setShader(null);p.setColor(musicGlass?0x20ffffff:0x40ffffff);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(dp(1));rect.inset(dp(.5f),dp(.5f));c.drawRoundRect(rect,dp(22),dp(22),p);p.setStyle(Paint.Style.FILL);}}

    final class Scrim extends View {Paint p=new Paint(3);Scrim(){super(MainActivity.this);}@Override protected void onSizeChanged(int w,int h,int ow,int oh){p.setShader(new LinearGradient(0,0,0,h,new int[]{0xb0040910,0x08040910,0x50040910,0xee080b13},new float[]{0f,.23f,.52f,1f},Shader.TileMode.CLAMP));}@Override protected void onDraw(Canvas c){c.drawRect(0,0,getWidth(),getHeight(),p);}}
    void updateWavePalette(Bitmap artwork){if(artwork==waveArtwork)return;waveArtwork=artwork;wavePalette=new int[]{0xffe6eaf0,0xff929aa8};if(artwork==null||artwork.isRecycled())return;long[] red=new long[64],green=new long[64],blue=new long[64];int[] votes=new int[64];for(int y=0;y<12;y++)for(int x=0;x<12;x++){int color=artwork.getPixel(Math.min(artwork.getWidth()-1,(2*x+1)*artwork.getWidth()/24),Math.min(artwork.getHeight()-1,(2*y+1)*artwork.getHeight()/24));if(Color.alpha(color)<128)continue;int r=Color.red(color),g=Color.green(color),b=Color.blue(color),bin=((r>>6)<<4)|((g>>6)<<2)|(b>>6);votes[bin]++;red[bin]+=r;green[bin]+=g;blue[bin]+=b;}int first=-1,second=-1;for(int i=0;i<64;i++)if(votes[i]>0&&(first<0||votes[i]>votes[first]))first=i;if(first<0)return;int r1=(int)(red[first]/votes[first]),g1=(int)(green[first]/votes[first]),b1=(int)(blue[first]/votes[first]);double best=0;for(int i=0;i<64;i++)if(i!=first&&votes[i]>0){double r=red[i]/(double)votes[i]-r1,g=green[i]/(double)votes[i]-g1,b=blue[i]/(double)votes[i]-b1,distance=r*r+g*g+b*b,score=votes[i]*Math.sqrt(distance);if(distance>3500&&score>best){best=score;second=i;}}if(second<0)second=first;float[] hsv=new float[3];int[] bins={first,second};for(int i=0;i<2;i++){int bin=bins[i],color=Color.rgb((int)(red[bin]/votes[bin]),(int)(green[bin]/votes[bin]),(int)(blue[bin]/votes[bin]));Color.colorToHSV(color,hsv);if(hsv[1]>.1f)hsv[1]=Math.min(.95f,Math.max(.6f,hsv[1]));hsv[2]=Math.max(i==0?.95f:.75f,hsv[2]);if(first==second&&i==1)hsv[2]*=.7f;wavePalette[i]=Color.HSVToColor(hsv);}}

    final class AudioWaveform extends View {final Paint paint=new Paint(3);final float[] levels=new float[6];int[] colors={0xffe6eaf0,0xff929aa8};AudioWaveform(){super(MainActivity.this);}void setColors(int[] next){if(Arrays.equals(colors,next))return;colors=next.clone();updateShader();}void updateShader(){paint.setShader(new LinearGradient(0,0,Math.max(1,getWidth()),0,colors,null,Shader.TileMode.CLAMP));invalidate();}@Override protected void onSizeChanged(int w,int h,int oldW,int oldH){updateShader();}void setLevels(float[] samples){for(int bar=0;bar<6;bar++){float sample=bar<samples.length?samples[bar]:0;float decibels=20f*(float)Math.log10(Math.max(.000001f,sample));float target=Math.max(0,Math.min(.92f,(decibels+52f)/46f));levels[bar]+=(target>levels[bar]?.9f:.65f)*(target-levels[bar]);}invalidate();}@Override protected void onDraw(Canvas canvas){float slot=getWidth()/6f;paint.setColor(Color.WHITE);paint.setStrokeWidth(dp(2.4f));paint.setStrokeCap(Paint.Cap.ROUND);for(int i=0;i<6;i++){float half=dp(1)+levels[i]*(getHeight()*.42f-dp(1)),x=(i+.5f)*slot;canvas.drawLine(x,getHeight()/2f-half,x,getHeight()/2f+half,paint);}}}

    final class Ambient extends View {Paint p=new Paint(3);int tint=0xff243d6b;Ambient(){super(MainActivity.this);}void tint(int c){tint=c;invalidate();}@Override protected void onDraw(Canvas c){c.drawColor(0xff080b13);p.setShader(new RadialGradient(getWidth()*.74f,getHeight()*.18f,getWidth()*.8f,new int[]{withAlpha(tint,150),0x00101a30},null,Shader.TileMode.CLAMP));c.drawRect(0,0,getWidth(),getHeight(),p);p.setShader(null);}}
    int withAlpha(int c,int alpha){return c&0xffffff|alpha<<24;}
    final class Glyph extends Drawable {String kind;int size;int ink=WHITE;Paint p=new Paint(3);Glyph(String k,int s){kind=k;size=s;}public int getIntrinsicWidth(){return size;}public int getIntrinsicHeight(){return size;}public void setAlpha(int a){p.setAlpha(a);}public void setColorFilter(android.graphics.ColorFilter f){p.setColorFilter(f);}public int getOpacity(){return android.graphics.PixelFormat.TRANSLUCENT;}void drawAt(Canvas c,float x,float y,int s){setBounds((int)x,(int)y,(int)x+s,(int)y+s);draw(c);}@Override public void draw(Canvas canvas){canvas.save();android.graphics.Rect r=getBounds();canvas.translate(r.left,r.top);canvas.scale(r.width()/24f,r.height()/24f);p.setColor(ink);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(1.65f);p.setStrokeCap(Paint.Cap.ROUND);p.setStrokeJoin(Paint.Join.ROUND);
        if(kind.equals("wifi")||kind.equals("offline")){for(int i=0;i<3;i++){float inset=2+i*3;canvas.drawArc(inset,5+i*3,24-inset,25-i*3,219,102,false,p);}p.setStyle(Paint.Style.FILL);canvas.drawCircle(12,19,1.4f,p);}
        else if(kind.equals("uninstall")){canvas.drawLine(4,6,20,6,p);canvas.drawLine(9,3,15,3,p);canvas.drawLine(6,6,7,21,p);canvas.drawLine(7,21,17,21,p);canvas.drawLine(17,21,18,6,p);canvas.drawLine(10,10,10,17,p);canvas.drawLine(14,10,14,17,p);}
        else if(kind.equals("removeDock")){canvas.drawRoundRect(3,4,21,13,2,2,p);canvas.drawLine(7,8,17,8,p);canvas.drawLine(12,14,12,21,p);canvas.drawLine(9,18,12,21,p);canvas.drawLine(12,21,15,18,p);}
        else if(kind.equals("inputs")){canvas.drawRoundRect(3,4,21,13,2,2,p);canvas.drawLine(7,8,17,8,p);canvas.drawLine(9,13,9,17,p);canvas.drawLine(15,13,15,17,p);canvas.drawLine(9,17,15,17,p);canvas.drawLine(12,17,12,22,p);}
        else if(kind.equals("display")){canvas.drawRoundRect(2,3,22,17,2,2,p);canvas.drawLine(12,17,12,21,p);canvas.drawLine(7,21,17,21,p);}
        else if(kind.equals("sound")){Path speaker=new Path();speaker.moveTo(3,9);speaker.lineTo(7,9);speaker.lineTo(12,5);speaker.lineTo(12,19);speaker.lineTo(7,15);speaker.lineTo(3,15);speaker.close();canvas.drawPath(speaker,p);canvas.drawArc(10,7,20,17,-55,110,false,p);canvas.drawArc(9,3,25,21,-50,100,false,p);}
        else if(kind.equals("play")||kind.equals("pause")||kind.equals("previous")||kind.equals("next")){p.setStyle(Paint.Style.FILL);if(kind.equals("pause")){canvas.drawRoundRect(6,4,10,20,1,1,p);canvas.drawRoundRect(14,4,18,20,1,1,p);}else if(kind.equals("play")){Path t=new Path();t.moveTo(6,3);t.lineTo(21,12);t.lineTo(6,21);t.close();canvas.drawPath(t,p);}else{boolean back=kind.equals("previous");if(back){canvas.translate(24,0);canvas.scale(-1,1);}for(int x:new int[]{3,11}){Path t=new Path();t.moveTo(x,5);t.lineTo(x+9,12);t.lineTo(x,19);t.close();canvas.drawPath(t,p);}canvas.drawRoundRect(20,5,22,19,1,1,p);}}
        else if(kind.equals("airplay")){canvas.drawLine(8,18,3,18,p);canvas.drawLine(3,18,3,4,p);canvas.drawLine(3,4,21,4,p);canvas.drawLine(21,4,21,18,p);canvas.drawLine(21,18,16,18,p);Path triangle=new Path();triangle.moveTo(12,14);triangle.lineTo(6,22);triangle.lineTo(18,22);triangle.close();canvas.drawPath(triangle,p);}
        else if(kind.equals("language")){canvas.drawCircle(12,12,9,p);canvas.drawOval(8,3,16,21,p);canvas.drawLine(3,12,21,12,p);canvas.drawArc(4,5,20,13,0,180,false,p);}
        else if(kind.equals("controls")){canvas.drawLine(4,8,20,8,p);canvas.drawLine(4,16,20,16,p);p.setStyle(Paint.Style.FILL);canvas.drawCircle(9,8,2.4f,p);canvas.drawCircle(16,16,2.4f,p);}
        else if(kind.equals("ethernet")){canvas.drawRoundRect(5,4,19,17,2,2,p);canvas.drawLine(9,20,15,20,p);canvas.drawLine(12,17,12,20,p);}
        else if(kind.equals("apps")||kind.equals("library")||kind.equals("system")){for(int x=4;x<18;x+=10)for(int y=4;y<18;y+=10)canvas.drawRoundRect(x,y,x+6,y+6,1.4f,1.4f,p);}
        else{canvas.drawRoundRect(3,5,21,18,2,2,p);canvas.drawLine(8,21,16,21,p);}
        canvas.restore();}}
